-- TitanGlobal ERP: acuerdos de abastecimiento y sus líneas (módulo 20, spec modulo20-acuerdos-abastecimiento-backend).
--
-- Un acuerdo es un contrato marco con un proveedor: fija un monto máximo y un período de vigencia. Cada línea define el
-- producto, el precio acordado y la cantidad comprometida; los consumos se acumulan en CantidadConsumida. Las reglas CK_
-- repiten en la base lo que ya valida la API, como segunda defensa ante datos cargados por fuera. Convención de nombres:
-- CK_<Tabla>_<Regla>.

CREATE TABLE "AcuerdosAbastecimiento" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "ProveedorId" integer NOT NULL,
    "Descripcion" character varying(500),
    "FechaInicio" timestamp with time zone NOT NULL,
    "FechaFin" timestamp with time zone NOT NULL,
    "MontoMaximo" numeric(18,2) NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AcuerdosAbastecimiento" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AcuerdosAbastecimiento_Proveedores_ProveedorId" FOREIGN KEY ("ProveedorId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AcuerdosAbastecimiento_Estado" CHECK ("Estado" IN ('Vigente', 'Suspendido', 'Cancelado')),
    CONSTRAINT "CK_AcuerdosAbastecimiento_MontoMaximo" CHECK ("MontoMaximo" > 0),
    CONSTRAINT "CK_AcuerdosAbastecimiento_Periodo" CHECK ("FechaFin" > "FechaInicio")
);
CREATE UNIQUE INDEX "IX_AcuerdosAbastecimiento_Numero" ON "AcuerdosAbastecimiento" ("Numero");
CREATE INDEX "IX_AcuerdosAbastecimiento_ProveedorId" ON "AcuerdosAbastecimiento" ("ProveedorId");

CREATE TABLE "LineasAcuerdoAbastecimiento" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "AcuerdoId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "PrecioAcordado" numeric(18,2) NOT NULL,
    "CantidadComprometida" integer NOT NULL,
    "CantidadConsumida" integer NOT NULL,
    CONSTRAINT "PK_LineasAcuerdoAbastecimiento" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_LineasAcuerdoAbastecimiento_AcuerdosAbastecimiento_AcuerdoId" FOREIGN KEY ("AcuerdoId") REFERENCES "AcuerdosAbastecimiento" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_LineasAcuerdoAbastecimiento_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_LineasAcuerdoAbastecimiento_PrecioAcordado" CHECK ("PrecioAcordado" > 0),
    CONSTRAINT "CK_LineasAcuerdoAbastecimiento_CantidadComprometida" CHECK ("CantidadComprometida" BETWEEN 1 AND 1000000),
    CONSTRAINT "CK_LineasAcuerdoAbastecimiento_CantidadConsumida" CHECK ("CantidadConsumida" >= 0 AND "CantidadConsumida" <= "CantidadComprometida")
);
CREATE UNIQUE INDEX "IX_LineasAcuerdoAbastecimiento_AcuerdoId_ProductoId" ON "LineasAcuerdoAbastecimiento" ("AcuerdoId", "ProductoId");
CREATE INDEX "IX_LineasAcuerdoAbastecimiento_ProductoId" ON "LineasAcuerdoAbastecimiento" ("ProductoId");
